# IES Training · MikroTik · Dos WAN con failover por rutas recursivas
# Probalo primero en un equipo de banco y en Safe Mode (Ctrl+X). Antes, un export.
:local wan1 "{{WAN1_IF}}"
:local wan2 "{{WAN2_IF}}"
:local gw1 "{{GW1}}"
:local gw2 "{{GW2}}"
:local t1a "{{TESTIGO1_A}}"
:local t1b "{{TESTIGO1_B}}"
:local t2a "{{TESTIGO2_A}}"
:local t2b "{{TESTIGO2_B}}"
:local dns "{{DNS}}"
# Testigos: una /32 por su proveedor (scope=10)
:if ([:len [/ip/route/find where comment="ies-testigo-isp1-a"]] = 0) do={/ip/route/add dst-address=$t1a gateway=$gw1 scope=10 comment="ies-testigo-isp1-a"} else={/ip/route/set [find where comment="ies-testigo-isp1-a"] dst-address=$t1a gateway=$gw1 scope=10}
:if ([:len [/ip/route/find where comment="ies-testigo-isp1-b"]] = 0) do={/ip/route/add dst-address=$t1b gateway=$gw1 scope=10 comment="ies-testigo-isp1-b"} else={/ip/route/set [find where comment="ies-testigo-isp1-b"] dst-address=$t1b gateway=$gw1 scope=10}
:if ([:len [/ip/route/find where comment="ies-testigo-isp2-a"]] = 0) do={/ip/route/add dst-address=$t2a gateway=$gw2 scope=10 comment="ies-testigo-isp2-a"} else={/ip/route/set [find where comment="ies-testigo-isp2-a"] dst-address=$t2a gateway=$gw2 scope=10}
:if ([:len [/ip/route/find where comment="ies-testigo-isp2-b"]] = 0) do={/ip/route/add dst-address=$t2b gateway=$gw2 scope=10 comment="ies-testigo-isp2-b"} else={/ip/route/set [find where comment="ies-testigo-isp2-b"] dst-address=$t2b gateway=$gw2 scope=10}
# Rutas por defecto recursivas: ISP1 distancia 1, ISP2 distancia 2
:if ([:len [/ip/route/find where comment="ies-default-isp1-a"]] = 0) do={/ip/route/add dst-address=0.0.0.0/0 gateway=$t1a target-scope=11 check-gateway=ping distance=1 comment="ies-default-isp1-a"} else={/ip/route/set [find where comment="ies-default-isp1-a"] dst-address=0.0.0.0/0 gateway=$t1a target-scope=11 check-gateway=ping distance=1}
:if ([:len [/ip/route/find where comment="ies-default-isp1-b"]] = 0) do={/ip/route/add dst-address=0.0.0.0/0 gateway=$t1b target-scope=11 check-gateway=ping distance=1 comment="ies-default-isp1-b"} else={/ip/route/set [find where comment="ies-default-isp1-b"] dst-address=0.0.0.0/0 gateway=$t1b target-scope=11 check-gateway=ping distance=1}
:if ([:len [/ip/route/find where comment="ies-default-isp2-a"]] = 0) do={/ip/route/add dst-address=0.0.0.0/0 gateway=$t2a target-scope=11 check-gateway=ping distance=2 comment="ies-default-isp2-a"} else={/ip/route/set [find where comment="ies-default-isp2-a"] dst-address=0.0.0.0/0 gateway=$t2a target-scope=11 check-gateway=ping distance=2}
:if ([:len [/ip/route/find where comment="ies-default-isp2-b"]] = 0) do={/ip/route/add dst-address=0.0.0.0/0 gateway=$t2b target-scope=11 check-gateway=ping distance=2 comment="ies-default-isp2-b"} else={/ip/route/set [find where comment="ies-default-isp2-b"] dst-address=0.0.0.0/0 gateway=$t2b target-scope=11 check-gateway=ping distance=2}
# Las rutas por defecto comunes a esos gateways compiten: se apagan, no se borran
/ip/route/disable [find where static and dst-address=0.0.0.0/0 and (gateway=$gw1 or gateway=$gw2)]
# Las dos salidas en la lista WAN, para el masquerade de fábrica
:foreach i in={$wan1;$wan2} do={:if ([:len [/interface/list/member/find where list=WAN and interface=$i]] = 0) do={/interface/list/member/add list=WAN interface=$i comment="ies-dos-wan"}}
# DNS del router que no sean testigos
/ip/dns/set servers=[:toarray $dns]
# Clientes DHCP o PPPoE que meten su propia ruta con distancia baja
:foreach c in=[/ip/dhcp-client/find where disabled=no and add-default-route=yes and default-route-distance<3] do={:put ("Ojo: el cliente DHCP de " . [/ip/dhcp-client/get $c interface] . " instala su ruta por defecto con distancia baja")}
:foreach c in=[/interface/pppoe-client/find where disabled=no and add-default-route=yes and default-route-distance<3] do={:put ("Ojo: el PPPoE " . [/interface/pppoe-client/get $c name] . " instala su ruta por defecto con distancia baja")}
:put "Listo: testigos, recursivas con distancias 1 y 2, lista WAN y DNS. Verificá con /ip/route/print where dst-address=0.0.0.0/0"
